    # Vertical bars: repeat the rectangular color tile attached at an end
    # along the length of the bar.
    for c in range(w):
        rows = [r for r in range(h) if g[r][c] == 5]
        if len(rows) < 2 or rows != list(range(rows[0], rows[-1] + 1)):
            continue
        top, bottom = rows[0], rows[-1]

        for seed_r in (bottom + 1, top - 1):
            if not 0 <= seed_r < h:
                continue
            seed_side = c + 1 if c + 1 < w and g[seed_r][c + 1] not in (0, 5) else c - 1
            if not 0 <= seed_side < w or g[seed_r][seed_side] in (0, 5):
                continue

            lo = seed_side
            while lo > 0 and g[seed_r][lo - 1] not in (0, 5):
                lo -= 1
            hi = seed_side
            while hi + 1 < w and g[seed_r][hi + 1] not in (0, 5):
                hi += 1

            seed_rows = [seed_r]
            rr = seed_r + (1 if seed_r < top else -1)
            while 0 <= rr < h and any(g[rr][x] not in (0, 5) for x in range(lo, hi + 1)):
                seed_rows.append(rr)
                rr += 1 if seed_r < top else -1
            seed_rows.sort()
            tile = [[g[rr][x] for x in range(lo, hi + 1)] for rr in seed_rows]

            for r in range(top, bottom + 1):
                pattern = tile[(r - seed_rows[0]) % len(tile)]
                for j, x in enumerate(range(lo, hi + 1)):
                    if g[r][x] == 0:
                        g[r][x] = pattern[j]
            break

    return g
